const CACHE_NAME = 'restaurant-template-cache-v1';
const ASSETS_TO_CACHE = [
  '/',
  '/menu',
  '/cart',
  '/styles/global.css',
  '/favicon.svg',
  '/favicon.ico',
  // Add any other core assets here (e.g., specific JavaScript bundles generated by Astro)
];

// Install event: Caching static assets
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => {
        console.log('[Service Worker] Caching all static assets');
        return cache.addAll(ASSETS_TO_CACHE);
      })
      .catch((error) => console.error('[Service Worker] Caching failed', error))
  );
});

// Activate event: Cleaning up old caches
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            console.log('[Service Worker] Deleting old cache:', cacheName);
            return caches.delete(cacheName);
          }
          return Promise.resolve();
        })
      );
    })
  );
});

// Fetch event: Serving assets from cache or network
self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request)
      .then((response) => {
        // Cache hit - return response
        if (response) {
          return response;
        }
        // No cache hit - fetch from network and add to cache
        return fetch(event.request).then((networkResponse) => {
          return caches.open(CACHE_NAME).then((cache) => {
            // Only cache successful GET requests, not range requests or extensions Astro uses (e.g., .ts, .mjs)
            const url = new URL(event.request.url);
            if (event.request.method === 'GET' && 
                networkResponse.ok && 
                !event.request.headers.has('range') && 
                !url.pathname.match(/\.(ts|mjs|map)$/))
             {
              cache.put(event.request, networkResponse.clone());
            }
            return networkResponse;
          });
        });
      })
      .catch((error) => {
        console.error('[Service Worker] Fetch failed', error);
        // You could return an offline page here
        // return caches.match('/offline.html');
      })
  );
});
